scwin.vScrenID = "ULDCOM91000.xml";
scwin.gShowloadYn = '';
scwin.gIsurCd; // 법인코드
scwin.gComAbbrv; // 법인명
scwin.gLdMktTp;
scwin.gMktTp;
scwin.gDepCd; //부서코드 추가 
scwin.vDigitalYn = "N";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");

    //alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};
scwin.fn_GetParentValue = function() {
    scwin.gLdMktTp = js_market;
    var pvd = scwin.fn_GetProvider();
    if (pvd != null) {
        scwin.gIsurCd = pvd.scwin.gIsurCd;
        txb_isur_cd.setValue(scwin.gIsurCd);
        if ($c.stf.trim(scwin.gIsurCd).length == 5) {
            fn_ReadBasicInfo();
        }
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !법인정보조회--;
클릭-- > function() {
    scwin.gIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    tab_corpinfo.setSelectedTabIndex(1);
    if (scwin.gIsurCd.length != 5) {
        $c.win.alert("회사코드 5자리를  입력하십시오.");
        txb_isur_cd.focus();
        return;
    }
    if (scwin.gMktTp == "2") {
        pnl_2.style.height = "970";
        $c.stf.showObj(pnl_seg, true);
        $c.stf.showObj(pnl_remnd, true);
    } else {
        pnl_2.style.height = "650";
        $c.stf.showObj(pnl_seg, false);
        $c.stf.showObj(pnl_remnd, false);
    }
    fn_ReadBasicInfo();
} < !법인--;
기본정보조회;
검색-- > function() {
    if (scwin.gIsurCd == undefined) return;
    scwin.gShowloadYn = 'N';
    showload.style.display = "";
    var url = "";

    // 기본정보조회
    if (js_bond_yn == "Y") {
        url = "/CorporationInfo.do?method=readCorpBasicInfo&inputMessageId=CORP_BASICINFO_OUT" + "&outputMessageId=CORP_BASICINFO_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&BOND_YN=" + js_bond_yn;
    } else {
        url = "/CorporationInfo.do?method=readCorpBasicInfo&inputMessageId=CORP_BASICINFO_OUT" + "&outputMessageId=CORP_BASICINFO_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&BOND_YN=N";
    }
    url = url + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_corp_basic.DataID = encodeURI(url);
    dts_corp_basic.reset();
    var vLdMktTp = dts_corp_basic.getCellData(1, "MKT_TP_CD");

    // 공시담당자1, 공시담당자(유, 코)
    var url1 = "";
    if (scwin.vDigitalYn == "Y") {
        url1 = "/digital/Digitalissueinfo.do?method=readDigitalPersonInCharge&Flag=2&ISUR_CD=" + scwin.gIsurCd;
    } else {
        url1 = "/ListedCompany.do?method=readChargeIssue&Flag=4&ISUR_CD=" + scwin.gIsurCd + "&MKT_TP_CD=" + vLdMktTp;
    }
    dts_Charge_Info.DataID = encodeURI(url1);
    dts_Charge_Info.Reset();

    // 공시담당자2, 공시실무자(유, 코)
    var url1_2 = "";
    if (scwin.vDigitalYn == "Y") {
        url1_2 = "/digital/Digitalissueinfo.do?method=readDigitalPersonInCharge&Flag=3&ISUR_CD=" + scwin.gIsurCd;
    } else {
        url1_2 = "/ListedCompany.do?method=readChargeIssue&Flag=5&ISUR_CD=" + scwin.gIsurCd + "&MKT_TP_CD=" + vLdMktTp;
    }
    dts_Charge_Info2.DataID = encodeURI(url1_2);
    dts_Charge_Info2.Reset();

    // 공시팀 담당자 조회		
    var url2 = "/ListedCompany.do?method=readChargeIssue&Flag=2&ISUR_CD=" + scwin.gIsurCd;
    dts_Krx_Emp_Info.DataID = encodeURI(url2);
    dts_Krx_Emp_Info.Reset();

    // 종목별 거래정지상태
    var url2_1 = "/CorporationInfo.do?method=readIsuHaltStat&inputMessageId=ISU_HALTSTAT_LIST_OUT" + "&outputMessageId=ISU_HALTSTAT_LIST_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_trdstop_stat.DataID = encodeURI(url2_1);
    dts_trdstop_stat.Reset();

    // 재무제표 추이 조회
    var url3 = "/CorporationInfo.do?method=readCorpFncStat&inputMessageId=CORP_FNCSTAT_OUT" + "&outputMessageId=CORP_FNCSTAT_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_fncstat.DataID = encodeURI(url3);
    dts_fncstat.reset();

    // 조회공시요구 건수 : 최근1년
    var url4 = "/CorporationInfo.do?method=readCorpInqdsclreqCnt&inputMessageId=CORP_INQDSCLREQ_CNT_OUT" + "&outputMessageId=CORP_INQDSCLREQ_CNT_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_inqdsclreq_cnt.DataID = encodeURI(url4);
    dts_inqdsclreq_cnt.reset();

    // 감사의견조회
    var url5 = "/CorporationInfo.do?method=listAudtWrtrptFnc&inputMessageId=AUDT_WRTRPT_FS_OUT" + "&outputMessageId=AUDT_WRTRPT_FS_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_audtwrtrpt_fnc3.DataID = encodeURI(url5);
    dts_audtwrtrpt_fnc3.reset();
} < !종목정보조회--;
검색-- > function() {
    //  우회상장관련 공시
    var url = "/CorporationInfo.do?method=listCorpBackdoorDscl&inputMessageId=CORP_BACKDRDSCL_LIST_OUT" + "&outputMessageId=CORP_BACKDRDSCL_LIST_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_backdoor_list.DataID = encodeURI(url);
    dts_backdoor_list.reset();

    //  상호변경
    var url1 = "/CorporationInfo.do?method=listCorpNmHistory&inputMessageId=CORP_NMHISTORY_LIST_OUT" + "&outputMessageId=CORP_NMHISTORY_LIST_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_corpnmhistory_list.DataID = encodeURI(url1);
    dts_corpnmhistory_list.reset();

    //  관리종목
    var url2 = "/CorporationInfo.do?method=listCorpAdmisu&inputMessageId=CORP_ADMISU_LIST_OUT" + "&outputMessageId=CORP_ADMISU_LIST_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&MKT_TP=" + scwin.gMktTp;
    dts_admisu_list.DataID = encodeURI(url2);
    dts_admisu_list.reset();

    //  불성실공시
    var url3 = "/CorporationInfo.do?method=listCorpNfaithDesign&inputMessageId=CORP_NFAITH_LIST_OUT" + "&outputMessageId=CORP_NFAITH_LIST_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_nfaith_list.DataID = encodeURI(url3);
    dts_nfaith_list.reset();
    if (scwin.gMktTp == "2") {
        var seg_url = "/CorporationInfo.do?method=getSegChgHist&inputMessageId=SEG_CHG_HIST_OUT" + "&outputMessageId=SEG_CHG_HIST_OUT" + "&ISUR_CD=" + scwin.gIsurCd; + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_seg_hist.DataID = encodeURI(seg_url);
        dts_seg_hist.reset();
        var remnd_url = "/CorporationInfo.do?method=getRemndList&inputMessageId=REMND_LIST_OUT" + "&outputMessageId=REMND_LIST_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
        dts_remnd_list.DataID = encodeURI(remnd_url);
        dts_remnd_list.reset();
    }
};




// 감사보고서제출 제무정보	정보조회 검색 
scwin.fn_ReadFncDataInfo = function() {
    var url = "/CorporationInfo.do?method=listAudtWrtrptFnc&inputMessageId=AUDT_WRTRPT_FS_OUT" + "&outputMessageId=AUDT_WRTRPT_FS_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_audtwrtrpt_fnc.DataID = encodeURI(url);
    dts_audtwrtrpt_fnc.reset();
    var url2 = "/CorporationInfo.do?method=listAudtWrtrptFncVertical&inputMessageId=AUDT_WRTRPT_FS_2_OUT" + "&outputMessageId=AUDT_WRTRPT_FS_2_OUT" + "&ISUR_CD=" + scwin.gIsurCd;
    dts_audtwrtrpt_fnc2.DataID = encodeURI(url2);
    dts_audtwrtrpt_fnc2.reset();
};
scwin.flash_scrtip = function(flashParam) {
    var flashStr = "";
    flashStr += "<iframe src='http://idev-kind.krx.co.kr/common/chart.do?method=loadInitPage&ispopup=true&isurcd=03949#' width='100%' height='600'></iframe>";
    return flashStr;
};
scwin.flash_scrtip_old = function(flashParam) {
    var flashStr = "";
    flashStr += "<object classid='clsid:D27CDB6E-AE6D-11cf-96B8-444553540000' id='chart' width='850' height='680' codebase='http://fpdownload.macromedia.com/pub/shockwave/cabs/flash/swflash.cab#version=9,0,0,0'>";
    flashStr += "<param name='movie' value='./STF_Chart.swf' />";
    flashStr += "<param name='quality' value='high' />";
    flashStr += "<param name='bgcolor' value='#ffffff' />";
    flashStr += "<param name='flashvars' value='" + flashParam + "'/>";
    flashStr += "<param name='allowScriptAccess' value='always' />";
    flashStr += "<embed src='./STF_Chart.swf' quality='high' bgcolor='#ffffff' width='100%' height='500' name='chart' align='middle' play='true' loop='false' quality='high' allowScriptAccess='always' type='application/x-shockwave-flash' pluginspage='http://www.macromedia.com/go/getflashplayer'/>";
    return flashStr;
};
scwin.fn_setFncStat = function(flag) {
    if (flag == '1') {
        //연결보고서
        txb_totasst_1.setValue(txb_CIFRS_ASST_AMT_1.getValue());
