        txb_totcap_1.setValue(txb_CIFRS_CAP_1.getValue());
        txb_totcap_3.setValue(txb_CIFRS_CAP_3.getValue());
        txb_totcap_4.setValue(txb_CIFRS_CAP_4.getValue());
        txb_cap_1.setValue(txb_CIFRS_CAPI_1.getValue());
        txb_cap_3.setValue(txb_CIFRS_CAPI_3.getValue());
