        txb_totasst_4.setValue(txb_IIFRS_ASST_AMT_4.getValue());
        txb_totdebt_1.setValue(txb_IIFRS_DEBT_AMT_1.getValue());
        txb_totdebt_3.setValue(txb_IIFRS_DEBT_AMT_3.getValue());
        txb_totdebt_4.setValue(txb_IIFRS_DEBT_AMT_4.getValue());
        txb_totcap_1.setValue(txb_IIFRS_CAP_1.getValue());
        txb_totcap_3.setValue(txb_IIFRS_CAP_3.getValue());
        txb_totcap_4.setValue(txb_IIFRS_CAP_4.getValue());
        txb_cap_1.setValue(txb_IIFRS_CAPI_1.getValue());
        txb_cap_3.setValue(txb_IIFRS_CAPI_3.getValue());
        txb_cap_4.setValue(txb_IIFRS_CAPI_4.getValue());
        txb_sales_1.setValue(txb_IIFRS_SALES_1.getValue());
        txb_sales_3.setValue(txb_IIFRS_SALES_3.getValue());
        txb_sales_4.setValue(txb_IIFRS_SALES_4.getValue());
        txb_bzproft_1.setValue(txb_IIFRS_BZ_PROFT_AMT_1.getValue());
        txb_bzproft_3.setValue(txb_IIFRS_BZ_PROFT_AMT_3.getValue());
        txb_bzproft_4.setValue(txb_IIFRS_BZ_PROFT_AMT_4.getValue());
        txb_bftaxnetpl_1.setValue(txb_IIFRS_BFTAX_NETPL_AMT_1.getValue());
        txb_bftaxnetpl_3.setValue(txb_IIFRS_BFTAX_NETPL_AMT_3.getValue());
        txb_bftaxnetpl_4.setValue(txb_IIFRS_BFTAX_NETPL_AMT_4.getValue());
        txb_netincm_1.setValue(txb_IIFRS_NETINCM_AMT_1.getValue());
