scwin.fn_getDateYmd = function(d) {
    if (d == "") return "-";
    return "'" + d.substring(2, 4) + "." + d.substring(4, 6) + "." + d.substring(6, 8);
};
scwin.fn_getDateY = function(d) {
    return "'" + d.substring(2, d.length);
};
scwin.fn_timer = function() {
    var date = new Date();

    /* 오늘 날짜를 구한다 */
    var curYear = date.getYear();
    var curMonth = (date.getMonth()) + 1;
    var curDay = date.getDate();
    return curYear + "-" + curMonth + "-" + curDay;
};
scwin.fn_numberWithCommas = function(type, n) {
    //종업원수
    if (type == "EMP_CNT") {
        if (n != "") return n.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + "명";
        return n;
    }
    //불성실 부과벌점
    else if (type == "ACC_PNLT") {
        if (n == "0") return "0.0점";
        var parts = n.toString().split(".");
        return parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",") + (parts[1] ? "." + parts[1] : "") + "점";
    }
    return n;
};
scwin.fn_getBlankCheck = function(type, param) {
    //시가총액
    if (type == "MKTCAP") {
        if (param != "") return param + " 억원";
    }
    if (param == "") return "-";
    return param;
};
scwin.fn_getEmpNoInfo = function() {
    var url = "/UnfaithfulDesignReport.do?method=readEmpNoInfo" + "&EMP_NO=" + js_emp_no;
    dts_EmpInfo.DataID = encodeURI(url);
    dts_EmpInfo.Reset();
};
