//시세데이터 로딩 2019-06-02 KBoY
scwin.getSiseNgonsiData = function() {
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    var myUrl = "/DsclChart.do?method=getChartContents" + "&isurcd=" + $c.stf.getObjectValue(txb_isur_cd) + "&fromdate=" + edt_FromDate.getValue() + "&todate=" + edt_ToDate.getValue() + "&dscltype=" + $c.cp.valueOfIndex(cmb_disclsTP, "VALUE", cmb_disclsTP.getSelectedIndex());
    $("#panel_1").load(myUrl).fadeIn("slow");
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};
scwin.isDigitalCheck = function() {
    var scr = scwin.fn_GetProvider();
    if (scr != null && scr != undefined && scr.scwin.vScrenID == "ULDSTF15660.gfm") {
        scwin.vDigitalYn = "Y";
        tab_corpinfo.DisableBackColor = "#999999";
        tab_corpinfo.setDisabled(true);
