scwin.dts_corp_basic_OnLoadError = function() {
    $c.stf.alert_error(dts_corp_basic);
};
scwin.dts_corp_basic_OnLoadCompleted = function(rowcount) {
    if (dts_corp_basic.errorMsg) {
        $c.win.alert(dts_corp_basic.errorMsg);
    } else {
        scwin.gMktTp = dts_corp_basic.getCellData(1, "MKT_TP_CD");
        //gMktTp = txb_mkt_tp.value;	// 발행기관의 시장구분
        scwin.gComAbbrv = txb_com_abbrv.getValue(); // 법인명

        if (scwin.gMktTp == '1') {
            $c.stf.setObjectValue(txb_label3, '[관리종목]');
            $c.stf.showObj(panel_opt1, true);
            $c.stf.showObj(panel_advisor, false); //현지정자문인20220624

        } else if (scwin.gMktTp == '6') {
            $c.stf.setObjectValue(txb_label3, '[관리종목]');
            $c.stf.showObj(panel_opt1, false);
            $c.stf.showObj(panel_advisor, true); //현지정자문인

        } else {
            //setObjectValue(txb_label3, '투자유의/관리종목');		//2008.07.15 수정요청
            $c.stf.setObjectValue(txb_label3, '[관리종목]');
            $c.stf.showObj(panel_opt1, false);
            $c.stf.showObj(panel_advisor, false); //현지정자문인

        }
        if (scwin.gMktTp == '2') {
            //코스닥인 경우에만 사전확인면제법인 / 공시우수법인 문구 표기
            var excnt_msg = "";
            var EXMPT_OBJ_DISCLS_YN = dts_corp_basic.getCellData(1, "EXMPT_OBJ_DISCLS_YN");
            var EXCNT_DISCLS_CORP_YN = dts_corp_basic.getCellData(1, "EXCNT_DISCLS_CORP_YN");
            if (EXMPT_OBJ_DISCLS_YN == 'Y' && EXCNT_DISCLS_CORP_YN == 'Y') {
                excnt_msg = '사전확인면제법인 / 공시우수법인';
            } else if (EXMPT_OBJ_DISCLS_YN == 'Y') {
                excnt_msg = '사전확인면제법인';
            } else if (EXCNT_DISCLS_CORP_YN == 'Y') {
                excnt_msg = '공시우수법인';
            }
            $c.stf.setObjectValue(txb_excnt_msg, excnt_msg);
            $c.stf.showObj(txb_excnt_msg, true);
        } else {
            $c.stf.setObjectValue(txb_excnt_msg, '');
        }
    }
};
