    txb_yy_r4.setValue(txb_yy_l4.getValue());

    // 총자산 2조이상일때, 즉 대규모법인  
    if (txb_big_yn.getValue() == 'Y') {
        txb_totasst_1.style.color = "#FF0000";
    }
