        //IFRS보고서 읽을때 
        $c.stf.showObj(rdo_FS, true);

        //IFRS일때 연결 개별 구분하여 둘다있을때 연결부터 개별만 있을때는 개별부터 보여준다.
        if (txb_CIFRS_ASST_AMT_1.getValue() == '' && txb_CIFRS_DEBT_AMT_1.getValue() == '' && txb_CIFRS_CAP_1.getValue() == '' && txb_CIFRS_CAPI_1.getValue() == '' &&
            txb_CIFRS_SALES_1.getValue() == '' && txb_CIFRS_BZ_PROFT_AMT_1.getValue() == '' && txb_CIFRS_BFTAX_NETPL_AMT_1.getValue() == '' && txb_CIFRS_NETINCM_AMT_1.getValue() == '') {
