        } else {
            scwin.fn_setFncStat('1');
            $c.stf.setObjectValue(rdo_FS, '1');
        }
    } else {
        //K-GAP보고서
        $c.stf.showObj(rdo_FS, false);
    }
    showload.style.display = "none";
    scwin.gShowloadYn = 'Y';
