scwin.tab_corpinfo_OnSelChanged = function(nIndex) {
    //*
    //이벤트가 중복해서 발생해서 주석처리 2011.08.05

    if (nIndex == 1) {
        // 첫번째 탭 클릭시 
        // 기본정보 데이타 읽어오기
        fn_ReadBasicInfo();
    } else if (nIndex == 2) {
        // 두번째 탭 클릭시 
        // 종목정보
        fn_ReadDsclInfo();
    } else if (nIndex == 3) {
        // 세번째 탭 클릭시 
        // 공시차트
        //$("#panel_1").empty().append("KBOY");
        scwin.getSiseNgonsiDataDefault();
        //panel_1.innerHTML =	flash_scrtip('isurcd='+txb_isur_cd.value) ;

