scwin.gform_onload = function() {
    // 패널라운드 처리

    $c.cm.PanelToGroupBox(pnl_1);
    $c.stf.showObj(panel_ifrs);
    scwin.isDigitalCheck();
    //PanelToGroupBox(pnl_BasicInfo);
    //PanelToGroupBox(pnl_2);
    //PanelToGroupBox(pnl_chart);
    scwin.fn_GetParentValue();
    $c.stf.showObj(panel_chk, false);
    $c.stf.showObj(txb_excnt_msg, false);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    tab_corpinfo.setSelectedTabIndex(1);
    scwin.gDepCd = js_dep_cd;
    if (scwin.gDepCd != '' && scwin.gDepCd == 'ZSYS') {
        //재무재표 출처는 시스템사용자만 보이게 한다 2018.02.09
        $c.stf.showObj(panel_form_cd, true);
    } else {
        $c.stf.showObj(panel_form_cd, false);
    }
    if (scwin.gMktTp == "1") {
        textbox_1.setValue("공시담당자(정)");
        textbox_2.setValue("공시담당자(부)");
        $c.stf.showObj(pnl_seg, false);
        $c.stf.showObj(pnl_remnd, false);
        pnl_2.style.height = "650";
    } else if (scwin.gMktTp == "2") {
        pnl_2.style.height = "970";
        $c.stf.showObj(pnl_seg, true);
        $c.stf.showObj(pnl_remnd, true);
    } else {
        pnl_2.style.height = "650";
        $c.stf.showObj(pnl_seg, false);
        $c.stf.showObj(pnl_remnd, false);
    }
    showload.style.display = "none";
};
